CREATE OR REPLACE FUNCTION public.validate_weekly_message() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.publication_state NOT IN ('draft','scheduled','delivered') THEN RAISE EXCEPTION 'Situação inválida'; END IF; IF NEW.publication_state<>'draft' AND (NEW.delivery_week IS NULL OR NEW.delivery_week<1) THEN RAISE EXCEPTION 'Escolha uma semana de entrega'; END IF; IF TG_OP='INSERT' AND NEW.publication_state='scheduled' AND EXISTS(SELECT 1 FROM public.letter_rounds WHERE number=NEW.delivery_week AND status='closed') THEN RAISE EXCEPTION 'Não é possível enviar para semana encerrada'; END IF; RETURN NEW; END $$;
CREATE TRIGGER z_validate_weekly_letter BEFORE INSERT OR UPDATE ON public.campaign_letters FOR EACH ROW EXECUTE FUNCTION public.validate_weekly_message();
CREATE TRIGGER z_validate_weekly_reply BEFORE INSERT OR UPDATE ON public.letter_replies FOR EACH ROW EXECUTE FUNCTION public.validate_weekly_message();
CREATE OR REPLACE FUNCTION public.schedule_letter_draft(p_id uuid,p_week integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer:=public.open_letter_round(); target integer; BEGIN IF NOT public.is_campaign_admin() AND n IS NULL THEN RAISE EXCEPTION 'Missivas fechadas, aguarde o narrador abrir a próxima semana'; END IF; target:=CASE WHEN public.is_campaign_admin() THEN p_week ELSE n END; IF target IS NULL OR target<1 OR EXISTS(SELECT 1 FROM public.letter_rounds WHERE number=target AND status='closed') THEN RAISE EXCEPTION 'Escolha uma semana preparada ou aberta'; END IF; UPDATE public.campaign_letters SET delivery_week=target,letter_number=target,creation_week=n,publication_state=CASE WHEN target=n THEN 'delivered' ELSE 'scheduled' END,delivered_at=CASE WHEN target=n THEN now() END WHERE id=p_id AND sender_user_id=auth.uid() AND publication_state='draft' AND btrim(subject)<>'' AND btrim(content)<>''; IF NOT FOUND THEN RAISE EXCEPTION 'Preencha o rascunho antes de enviar'; END IF; INSERT INTO public.sync_outbox(entity_type,entity_id,version,payload) SELECT 'letter',id,version,to_jsonb(l) FROM public.campaign_letters l WHERE id=p_id ON CONFLICT DO NOTHING; UPDATE public.sync_outbox SET state='pending',next_attempt_at=now() WHERE entity_id=p_id; END $$;
ALTER POLICY campaign_images_read ON storage.objects USING (bucket_id='campaign-images' AND (public.is_campaign_admin() OR (storage.foldername(name))[1]=auth.uid()::text OR EXISTS(SELECT 1 FROM public.campaign_letters l WHERE l.publication_state='delivered' AND public.can_read_letter(l) AND position('[cormyr-image:'||objects.name||'|' in l.content)>0) OR EXISTS(SELECT 1 FROM public.letter_replies r WHERE r.publication_state='delivered' AND public.can_read_reply(r) AND position('[cormyr-image:'||objects.name||'|' in r.content)>0) OR EXISTS(SELECT 1 FROM public.campaign_records r WHERE public.can_read_record(r) AND position('[cormyr-image:'||objects.name||'|' in r.content)>0)));